import re

class Solution:
    def removeComments(self, source: list[str]) -> list[str]:
        text = '\n'.join(source)
        cleaned = re.sub(r'/\*.*?\*/|//[^\n]*', '', text, flags=re.DOTALL)
        return [line for line in cleaned.split('\n') if line]
